void Check(bool ok,string message){if(!ok)throw new System.Exception(message);}
var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
var menu=UnityEngine.Object.FindAnyObjectByType<CrewMenu>();var storm=UnityEngine.Resources.Load<ShipMissionDefinition>("Missions/G02_Solar_Storm");var intro=UnityEngine.Resources.Load<ShipMissionDefinition>("Missions/G01_LEO_Check");ShipMission mission=null;
void Set(string field,object value)=>typeof(ShipMission).GetField(field,flags).SetValue(mission,value);
async System.Threading.Tasks.Task NewFlight(){if(UnityEngine.Object.FindAnyObjectByType<ShipMission>()!=null){menu.SendMessage("ReturnToMenu");await System.Threading.Tasks.Task.Delay(80);}menu.SendMessage("Confirm");await System.Threading.Tasks.Task.Delay(100);mission=UnityEngine.Object.FindAnyObjectByType<ShipMission>();mission.enabled=false;Set("runPlan",new[]{new MissionRunPlan.Entry{definition=intro,trigger=0},new MissionRunPlan.Entry{definition=storm,trigger=135}});Set("missionDefinitions",new[]{intro,storm});((System.Collections.IDictionary)typeof(ShipMission).GetField("missionStatuses",flags).GetValue(mission))[intro]=ShipMissionStatus.Completed;}
void AtShelter(){var p=mission.GetComponentInChildren<CrewCharacter>();p.transform.position=(UnityEngine.Vector3)storm.WorldPosition+UnityEngine.Vector3.back;Set("deck",0);Set("activeLadder",-1);}
await NewFlight();
var alert=(UnityEngine.GameObject)typeof(CrewMenu).GetField("stormSuggestion",flags).GetValue(menu);var title=(UnityEngine.UI.Text)typeof(CrewMenu).GetField("stormAlertTitle",flags).GetValue(menu);var instruction=(UnityEngine.UI.Text)typeof(CrewMenu).GetField("stormAlertInstruction",flags).GetValue(menu);
Set("missionClock",134f);mission.SendMessage("UpdateFlightEvents");menu.SendMessage("UpdateStormSuggestion");Check(!alert.activeSelf&&mission.RadiationLevel==0,"Radiation appears before story release");
Set("missionClock",135f);mission.SendMessage("UpdateFlightEvents");menu.SendMessage("UpdateStormSuggestion");Check(alert.activeInHierarchy&&title.text.Contains("HP LOSS")&&mission.ActiveMission==null,"Radiation is not an automatic interior event");
mission.SendMessage("UpdateCabinRadiation",5f);Check(UnityEngine.Mathf.Abs(mission.Health.Current-96.5f)<.001,"Interior field causes no continuous health damage");
menu.SendMessage("UpdateRadiationStatus");var radiation=(UnityEngine.UI.Text)typeof(CrewMenu).GetField("radiationStatus",flags).GetValue(menu);Check(radiation.text.Contains("CABIN")&&radiation.text.Contains("35%")&&radiation.text.Contains("0.70")&&radiation.text.Contains("HP"),"Damage rate missing from radiation HUD");
AtShelter();menu.SendMessage("OpenMissionCard",storm);menu.SendMessage("StartSelectedMission");menu.SendMessage("CloseMissionCard");menu.SendMessage("UpdateStormSuggestion");Check(title.text.Contains("CABIN")&&instruction.text.Contains("90s"),"Active warning not persistent");
menu.SendMessage("TogglePause");float health=mission.Health.Current;float remaining=mission.ActiveMissionSecondsRemaining;mission.SendMessage("UpdateCabinRadiation",10f);mission.SendMessage("UpdateActiveMission",10f);Check(mission.Health.Current==health&&mission.ActiveMissionSecondsRemaining==remaining,"Pause advances storm or exposure");menu.SendMessage("TogglePause");
Check(mission.TryInteract()&&mission.ProcedureStepIndex==1,"Shelter arrival cannot advance procedure");while(mission.ActiveMission!=null){var step=mission.CurrentStep;if(step.automatic)mission.SendMessage("UpdateActiveMission",step.durationSeconds);else Check(mission.ChooseProcedureOption(step.correctChoice),"Shelter equipment choice rejected");}
Check(mission.GetMissionStatus(storm)==ShipMissionStatus.Completed&&mission.IsRadiationProtected&&mission.RadiationLevel==35,"Success does not create local shielding or erases the whole cabin field");health=mission.Health.Current;mission.SendMessage("UpdateCabinRadiation",10f);Check(mission.Health.Current==health,"Protected shelter still loses HP");
menu.SendMessage("UpdateStormSuggestion");Check(alert.activeSelf&&title.text.Contains("SHELTERED"),"Protected cabin hazard not visible");mission.SendMessage("UpdateCabinRadiation",mission.CabinEventSecondsRemaining);Check(mission.RadiationLevel==0,"Cabin field does not clear after the event");
await NewFlight();Set("missionClock",135f);mission.SendMessage("UpdateFlightEvents");AtShelter();Check(mission.StartMission(storm),"Cannot start storm at shelter");mission.SendMessage("UpdateActiveMission",91f);Check(mission.GetMissionStatus(storm)==ShipMissionStatus.Failed&&mission.Health.Current==75,"One-shot failure damage missing");mission.SendMessage("UpdateActiveMission",91f);Check(mission.Health.Current==75,"Duplicate failure damage");
mission.SendMessage("UpdateCabinRadiation",10f);Check(mission.Health.Current<75,"Failing procedure disables the cabin hazard");menu.SendMessage("UpdateStormSuggestion");Check(alert.activeSelf&&title.text.Contains("HP LOSS"),"Ongoing cabin hazard becomes invisible after failure");
menu.SendMessage("ReturnToMenu");return "PASS: automatic cabin event, continuous HP drain and rate HUD before accepting task; paused clocks/exposure, physical shelter sequence and local protection, persistent exposed/protected warnings, natural clearing, one-shot procedure failure plus continuing cabin exposure";
